contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address target, uint preFund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (preFund) + (amount)); require(preFund <= 1000000000000000000000000000000); require(amount <= 1000000000000000000000000000000);
        require(target != address(0), "target zero");
        require(preFund > 0, "preFund positive");
        require(address(this).balance >= preFund + amount, "balance insufficient");

        // Fund c so c has a positive starting balance; msg.sender is address(this).
        c.Command{value: preFund}(address(this), ""); if (__ESBMC_reverted()) return;

        uint before_c = address(c).balance;

        bool reverted;
        c.multiplicate{value: amount}(target); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint after_c = address(c).balance;

        assert(reverted ? after_c == before_c : after_c == before_c + amount);
    }

    receive() external payable {}
}

