// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 amount, address target, uint256 preFund) internal {
        preFund = bound(preFund, 0, 1000000000000000000000000000000);
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(target != address(0));
        vm.assume(preFund > 0);
        vm.assume(address(this).balance >= preFund + amount);
        try c.Command{value: preFund}(address(this), "") {} catch { return; }
        uint before_c = address(c).balance;
        bool reverted;
        try c.multiplicate{value: amount}(target) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint after_c = address(c).balance;
        assertTrue(reverted ? after_c == before_c : after_c == before_c + amount);
    }

    function testFuzz_run(uint256 amount, address target, uint256 preFund) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, target, preFund);
    }

    receive() external payable {}
}
